-- ==================================================
-- Verification
-- ==================================================

SELECT
    nm.near_miss_id,
    nm.near_miss_number,
    nm.event_datetime,
    nm.plant_id,
    s.status_name,
    rr.rating_name,
    nm.contractor_involved,
    nm.further_investigation_required
FROM near_misses nm
JOIN plants p ON p.plant_id = nm.plant_id
JOIN statuses s ON s.status_id = nm.status_id
JOIN risk_ratings rr ON rr.risk_rating_id = nm.risk_rating_id
WHERE nm.deleted_at IS NULL
ORDER BY nm.event_datetime;
